scwin.img_72_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31203.img_72_onmouseover' }); }
};

/**
 * @method
 * @name ipt_premiumRate_onkeypress
 * @description ipt_premiumRate onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_premiumRate_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31203.ipt_premiumRate_onkeypress' }); }
};

