///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal9
 * @description cal9 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal9 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]를 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('cal_decisionDate').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDate').getValue())) === '') {
        await $c.win.alert("[이사회결의일]을 입력하세요.");
        $c.util.getComponent("cal_decisionDate").focus();
        return;
    }
    if (($c.util.getComponent('cal_beforeThreeDay').getValue() == null ? '' : String($c.util.getComponent('cal_beforeThreeDay').getValue())) === '') {
        await $c.win.alert("[납입일전 3거래일]을 입력하세요.");
        $c.util.getComponent("cal_beforeThreeDay").focus();
        return;
    }
    if (($c.util.getComponent('ipt_premiumRate').getValue() == null ? '' : String($c.util.getComponent('ipt_premiumRate').getValue())) === '' && ($c.util.getComponent('ipt_discountRate').getValue() == null ? '' : String($c.util.getComponent('ipt_discountRate').getValue())) === '') {
        await $c.win.alert("할증율 또는 할인율 둘중 하나 이상은 값을 입력해야합니다.");
        return;
    }
    const sDecisionDate = $c.util.getComponent('cal_decisionDate').getValue();
    const sBeforeThreeDay = $c.util.getComponent('cal_beforeThreeDay').getValue();
    const nextMonth = scwin.addMonthsToDate(sDecisionDate.substring(0, 4), sDecisionDate.substring(4, 6), sDecisionDate.substring(6, 8), 1);
    if (($c.util.getComponent('rd_sellIntval').getValue() === '0')) {
        if (nextMonth > sBeforeThreeDay) {
            await $c.win.alert("[이사회결의일 ~ 납입일전 3거래일] 간 간격이 1개월 미만입니다.");
            return;
        }
    } else {
        if (nextMonth <= sBeforeThreeDay) {
            await $c.win.alert("[이사회결의일 ~ 납입일전 3거래일] 간 간격이 1개월 이상입니다.");
            return;
        }
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    await scwin.callProcessCalculateRelatedDisclosure9();
    await scwin.callProcessCalculateRelatedDisclosure9ToExcel();
};

/**
 * @method
 * @name addMonthsToDate
 * @description add Months To Date 처리
 * @param {*} yyyy yyyy
 * @param {*} mm mm
 * @param {*} dd dd
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.addMonthsToDate = function (yyyy, mm, dd, val) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.utils.cGetMinusDate, $c.utils.cGetZero
    let iYear = new Number(yyyy);
    let iMonth = new Number(mm);
    let iDay = new Number(dd);
    let ival = new Number(val);
    let iAddYear = 0;
    if (ival >= 12) {
        iAddYear = new Number(ival / 12);
        iYear = iYear + iAddYear;
        iMonth = iMonth + (ival % 12);
    } else {
        ival += iMonth;
        if (ival > 12) {
            iYear = iYear + 1;
            iMonth = ival - 12;
        } else {
            iMonth = ival;
        }
    }
    iMaxDay = $c.date.getLastDateOfMonth(iYear, iMonth);
    if (iDay > iMaxDay) {
        iDay = iMaxDay;
    }
    return $c.utils.cGetMinusDate(iYear.toString(), $c.utils.cGetZero(iMonth.toString(), 2), $c.utils.cGetZero(iDay.toString(), 2), 0);
};

